CREATE TABLE [dbo].[dim_book] (
    [book_key] int IDENTITY(1,1) NOT NULL,
    [book_id] int NOT NULL,
    [title] varchar(400) COLLATE Latin1_General_CI_AS NULL,
    [isbn13] char(13) COLLATE Latin1_General_CI_AS NULL,
    [num_pages] int NULL,
    [publication_date] date NULL,
    [publication_year] smallint NULL,
    [publisher_name] varchar(400) COLLATE Latin1_General_CI_AS NULL,
    [language_code] varchar(8) COLLATE Latin1_General_CI_AS NULL,
    [language_name] varchar(50) COLLATE Latin1_General_CI_AS NULL,
    [language_group] varchar(20) COLLATE Latin1_General_CI_AS NOT NULL,
    CONSTRAINT [pk_dim_book] PRIMARY KEY CLUSTERED ([book_key]),
    CONSTRAINT [uq_dim_book_bk] UNIQUE NONCLUSTERED ([book_id])
);
GO
CREATE TABLE [dbo].[dim_customer] (
    [customer_key] int IDENTITY(1,1) NOT NULL,
    [customer_id] int NOT NULL,
    [first_name] varchar(200) COLLATE Latin1_General_CI_AS NULL,
    [last_name] varchar(200) COLLATE Latin1_General_CI_AS NULL,
    [full_name] varchar(401) COLLATE Latin1_General_CI_AS NULL,
    [email] varchar(350) COLLATE Latin1_General_CI_AS NULL,
    [email_domain] varchar(200) COLLATE Latin1_General_CI_AS NULL,
    [heard_about] varchar(50) COLLATE Latin1_General_CI_AS NOT NULL,
    [preferred_channel] varchar(50) COLLATE Latin1_General_CI_AS NOT NULL,
    [survey_responded] bit NOT NULL,
    CONSTRAINT [pk_dim_customer] PRIMARY KEY CLUSTERED ([customer_key]),
    CONSTRAINT [uq_dim_customer_bk] UNIQUE NONCLUSTERED ([customer_id])
);
GO
CREATE TABLE [dbo].[dim_date] (
    [date_key] int NOT NULL,
    [full_date] date NULL,
    [day_of_month] tinyint NULL,
    [day_name] varchar(10) COLLATE Latin1_General_CI_AS NULL,
    [month_num] tinyint NULL,
    [month_name] varchar(10) COLLATE Latin1_General_CI_AS NULL,
    [quarter_num] tinyint NULL,
    [quarter_label] char(2) COLLATE Latin1_General_CI_AS NULL,
    [year_num] smallint NULL,
    [year_month] char(7) COLLATE Latin1_General_CI_AS NULL,
    [year_quarter] char(7) COLLATE Latin1_General_CI_AS NULL,
    [campaign_period] varchar(20) COLLATE Latin1_General_CI_AS NOT NULL,
    CONSTRAINT [pk_dim_date] PRIMARY KEY CLUSTERED ([date_key])
);
GO
CREATE TABLE [dbo].[dim_location] (
    [location_key] int IDENTITY(1,1) NOT NULL,
    [address_id] int NOT NULL,
    [street_number] varchar(10) COLLATE Latin1_General_CI_AS NULL,
    [street_name] varchar(200) COLLATE Latin1_General_CI_AS NULL,
    [city] varchar(100) COLLATE Latin1_General_CI_AS NULL,
    [country_id] int NULL,
    [country_name] varchar(200) COLLATE Latin1_General_CI_AS NOT NULL,
    [region] varchar(50) COLLATE Latin1_General_CI_AS NOT NULL,
    [country_status] varchar(20) COLLATE Latin1_General_CI_AS NOT NULL,
    CONSTRAINT [pk_dim_location] PRIMARY KEY CLUSTERED ([location_key]),
    CONSTRAINT [uq_dim_location_bk] UNIQUE NONCLUSTERED ([address_id])
);
GO
CREATE TABLE [dbo].[dim_shipping_method] (
    [shipping_key] int IDENTITY(1,1) NOT NULL,
    [method_id] int NOT NULL,
    [method_name] varchar(100) COLLATE Latin1_General_CI_AS NOT NULL,
    [cost] decimal(6,2) NULL,
    CONSTRAINT [pk_dim_shipping] PRIMARY KEY CLUSTERED ([shipping_key]),
    CONSTRAINT [uq_dim_shipping_bk] UNIQUE NONCLUSTERED ([method_id])
);
GO
CREATE TABLE [dq].[check_log] (
    [check_id] int IDENTITY(1,1) NOT NULL,
    [run_time] datetime2(7) NOT NULL,
    [check_name] varchar(100) COLLATE Latin1_General_CI_AS NOT NULL,
    [dq_dimension] varchar(20) COLLATE Latin1_General_CI_AS NOT NULL,
    [table_name] varchar(100) COLLATE Latin1_General_CI_AS NOT NULL,
    [failed_rows] int NOT NULL,
    [severity] varchar(10) COLLATE Latin1_General_CI_AS NOT NULL,
    [treatment] varchar(300) COLLATE Latin1_General_CI_AS NULL,
    PRIMARY KEY CLUSTERED ([check_id])
);
GO
CREATE TABLE [etl].[audit] (
    [audit_id] int IDENTITY(1,1) NOT NULL,
    [package_name] varchar(100) COLLATE Latin1_General_CI_AS NOT NULL,
    [task_name] varchar(100) COLLATE Latin1_General_CI_AS NOT NULL,
    [table_name] varchar(100) COLLATE Latin1_General_CI_AS NULL,
    [rows_read] int NULL,
    [rows_written] int NULL,
    [rows_rejected] int NULL,
    [start_time] datetime2(7) NOT NULL CONSTRAINT [DF__audit__start_tim__628FA481] DEFAULT (sysdatetime()),
    [end_time] datetime2(7) NULL,
    [status] varchar(20) COLLATE Latin1_General_CI_AS NOT NULL CONSTRAINT [DF__audit__status__6383C8BA] DEFAULT ('Running'),
    PRIMARY KEY CLUSTERED ([audit_id])
);
GO
CREATE TABLE [etl].[config] (
    [config_key] varchar(50) COLLATE Latin1_General_CI_AS NOT NULL,
    [config_value] varchar(200) COLLATE Latin1_General_CI_AS NOT NULL,
    [description] varchar(400) COLLATE Latin1_General_CI_AS NULL,
    PRIMARY KEY CLUSTERED ([config_key])
);
GO
CREATE TABLE [dbo].[fact_sales] (
    [sales_key] bigint IDENTITY(1,1) NOT NULL,
    [order_date_key] int NOT NULL,
    [customer_key] int NOT NULL,
    [book_key] int NOT NULL,
    [location_key] int NOT NULL,
    [shipping_key] int NOT NULL,
    [order_id] int NOT NULL,
    [line_id] int NOT NULL,
    [sales_amount] decimal(7,2) NOT NULL,
    [quantity] int NOT NULL CONSTRAINT [df_fact_qty] DEFAULT ((1)),
    [latest_order_status] varchar(20) COLLATE Latin1_General_CI_AS NOT NULL,
    [is_cancelled_or_returned] bit NOT NULL,
    CONSTRAINT [pk_fact_sales] PRIMARY KEY CLUSTERED ([sales_key]),
    CONSTRAINT [uq_fact_sales_line] UNIQUE NONCLUSTERED ([line_id])
);
GO
CREATE TABLE [dq].[fact_rejects] (
    [reject_id] int IDENTITY(1,1) NOT NULL,
    [line_id] int NULL,
    [order_id] int NULL,
    [book_id] int NULL,
    [price] decimal(7,2) NULL,
    [reject_reason] varchar(200) COLLATE Latin1_General_CI_AS NOT NULL,
    [reject_time] datetime2(7) NOT NULL CONSTRAINT [DF__fact_reje__rejec__68487DD7] DEFAULT (sysdatetime()),
    PRIMARY KEY CLUSTERED ([reject_id])
);
GO
