ALTER TABLE [dbo].[fact_sales] WITH CHECK ADD CONSTRAINT [fk_fact_book] FOREIGN KEY ([book_key]) REFERENCES [dbo].[dim_book] ([book_key]);
ALTER TABLE [dbo].[fact_sales] WITH CHECK ADD CONSTRAINT [fk_fact_customer] FOREIGN KEY ([customer_key]) REFERENCES [dbo].[dim_customer] ([customer_key]);
ALTER TABLE [dbo].[fact_sales] WITH CHECK ADD CONSTRAINT [fk_fact_date] FOREIGN KEY ([order_date_key]) REFERENCES [dbo].[dim_date] ([date_key]);
ALTER TABLE [dbo].[fact_sales] WITH CHECK ADD CONSTRAINT [fk_fact_location] FOREIGN KEY ([location_key]) REFERENCES [dbo].[dim_location] ([location_key]);
ALTER TABLE [dbo].[fact_sales] WITH CHECK ADD CONSTRAINT [fk_fact_shipping] FOREIGN KEY ([shipping_key]) REFERENCES [dbo].[dim_shipping_method] ([shipping_key]);
