CREATE NONCLUSTERED INDEX [ix_fact_book] ON [dbo].[fact_sales] ([book_key]);
CREATE NONCLUSTERED INDEX [ix_fact_date] ON [dbo].[fact_sales] ([order_date_key]);
CREATE NONCLUSTERED INDEX [ix_fact_location] ON [dbo].[fact_sales] ([location_key]);
GO
-- rpt.v_book_sales
/* ---------------- Q3 + Q4: one row per book ------------------------- */
CREATE   VIEW rpt.v_book_sales AS
WITH b AS (
    SELECT bk.book_key, bk.book_id, bk.title, bk.num_pages, bk.publication_year,
           bk.publisher_name, bk.language_name, bk.language_group,
           COUNT(f.sales_key)             AS units_sold,
           ISNULL(SUM(f.sales_amount), 0) AS sales,
           CAST(AVG(f.sales_amount) AS decimal(6,2)) AS avg_price
    FROM dbo.dim_book bk
    LEFT JOIN dbo.fact_sales f ON f.book_key = bk.book_key
    WHERE bk.book_key > 0
    GROUP BY bk.book_key, bk.book_id, bk.title, bk.num_pages, bk.publication_year,
             bk.publisher_name, bk.language_name, bk.language_group
)
SELECT b.*,
       CASE WHEN units_sold = 0 THEN 0 ELSE 1 END AS has_sold,
       CASE WHEN num_pages IS NULL OR num_pages = 0 THEN 0
            WHEN num_pages < 200 THEN 1 WHEN num_pages < 400 THEN 2
            WHEN num_pages < 600 THEN 3 WHEN num_pages < 800 THEN 4 ELSE 5 END AS page_band_order,
       CASE WHEN num_pages IS NULL OR num_pages = 0 THEN 'Unknown'
            WHEN num_pages < 200 THEN 'Under 200' WHEN num_pages < 400 THEN '200 - 399'
            WHEN num_pages < 600 THEN '400 - 599' WHEN num_pages < 800 THEN '600 - 799'
            ELSE '800 and over' END AS page_band,
       CASE WHEN avg_price IS NULL THEN 'Not sold'
            WHEN avg_price <  5 THEN 'Under 5' WHEN avg_price < 10 THEN '5 - 9.99'
            WHEN avg_price < 15 THEN '10 - 14.99' ELSE '15 and over' END AS avg_price_band,
       CAST(publication_year / 10 * 10 AS varchar(4)) + 's' AS publication_decade
FROM b;
GO
-- rpt.v_campaign_effect
/* ---------------- Q4: campaign effect ------------------------------- */
CREATE   VIEW rpt.v_campaign_effect AS
SELECT d.campaign_period,
       COUNT(DISTINCT d.year_month) AS months,
       COUNT(*)                     AS units,
       SUM(f.sales_amount)          AS sales,
       CAST(SUM(f.sales_amount) / COUNT(DISTINCT d.year_month) AS decimal(10,2)) AS avg_monthly_sales
FROM dbo.fact_sales f JOIN dbo.dim_date d ON d.date_key = f.order_date_key
GROUP BY d.campaign_period;
GO
-- rpt.v_country_sales
/* ---------------- Q5: country totals, rank and 12-month trend ------- */
CREATE   VIEW rpt.v_country_sales AS
WITH bounds AS (
    SELECT MAX(d.full_date) AS last_date
    FROM dbo.fact_sales f JOIN dbo.dim_date d ON d.date_key = f.order_date_key
),
c AS (
    SELECT l.country_name, l.region,
           COUNT(DISTINCT f.customer_key) AS customers,
           COUNT(*)                       AS units,
           SUM(f.sales_amount)            AS sales,
           SUM(CASE WHEN d.full_date > DATEADD(YEAR, -1, b.last_date) THEN f.sales_amount ELSE 0 END) AS last_12m_sales,
           SUM(CASE WHEN d.full_date > DATEADD(YEAR, -2, b.last_date)
                     AND d.full_date <= DATEADD(YEAR, -1, b.last_date) THEN f.sales_amount ELSE 0 END) AS prior_12m_sales
    FROM dbo.fact_sales f
    JOIN dbo.dim_date d     ON d.date_key = f.order_date_key
    JOIN dbo.dim_location l ON l.location_key = f.location_key
    CROSS JOIN bounds b
    GROUP BY l.country_name, l.region
)
SELECT country_name, region, customers, units, sales,
       RANK() OVER (ORDER BY sales DESC)                                   AS sales_rank,
       CAST(100.0 * sales / SUM(sales) OVER () AS decimal(5,1))            AS pct_of_total,
       prior_12m_sales, last_12m_sales,
       CAST(100.0 * (last_12m_sales - prior_12m_sales) / NULLIF(prior_12m_sales, 0) AS decimal(6,1)) AS pct_change_12m,
       CASE WHEN prior_12m_sales = 0 THEN 'New'
            WHEN last_12m_sales > prior_12m_sales * 1.05 THEN 'Growing'
            WHEN last_12m_sales < prior_12m_sales * 0.95 THEN 'Declining'
            ELSE 'Flat' END                                                AS trend
FROM c;
GO
-- rpt.v_customer_factors
/* ---------------- Q4: customer-side factors ------------------------- */
CREATE   VIEW rpt.v_customer_factors AS
SELECT 'Heard about' AS factor, c.heard_about AS level_name,
       COUNT(DISTINCT c.customer_key) AS customers, COUNT(*) AS units,
       SUM(f.sales_amount) AS sales,
       CAST(SUM(f.sales_amount) / COUNT(DISTINCT c.customer_key) AS decimal(8,2)) AS sales_per_customer
FROM dbo.fact_sales f JOIN dbo.dim_customer c ON c.customer_key = f.customer_key
GROUP BY c.heard_about
UNION ALL
SELECT 'Preferred channel', c.preferred_channel,
       COUNT(DISTINCT c.customer_key), COUNT(*), SUM(f.sales_amount),
       CAST(SUM(f.sales_amount) / COUNT(DISTINCT c.customer_key) AS decimal(8,2))
FROM dbo.fact_sales f JOIN dbo.dim_customer c ON c.customer_key = f.customer_key
GROUP BY c.preferred_channel
UNION ALL
SELECT 'Shipping method', s.method_name,
       COUNT(DISTINCT f.customer_key), COUNT(*), SUM(f.sales_amount),
       CAST(SUM(f.sales_amount) / COUNT(DISTINCT f.customer_key) AS decimal(8,2))
FROM dbo.fact_sales f JOIN dbo.dim_shipping_method s ON s.shipping_key = f.shipping_key
GROUP BY s.method_name;
GO
-- rpt.v_factor_spread
/* ---------------- Q4: how strongly each book factor matters --------- */
CREATE   VIEW rpt.v_factor_spread AS
WITH levels AS (
    SELECT 'Language group' AS factor, language_group AS level_name, sales FROM rpt.v_book_sales
    UNION ALL SELECT 'Language', language_name, sales FROM rpt.v_book_sales
    UNION ALL SELECT 'Publication decade', publication_decade, sales FROM rpt.v_book_sales
    UNION ALL SELECT 'Page band', page_band, sales FROM rpt.v_book_sales
    UNION ALL SELECT 'Publisher', publisher_name, sales FROM rpt.v_book_sales
),
per_level AS (
    SELECT factor, level_name, COUNT(*) AS books, AVG(sales) AS avg_sales_per_book
    FROM levels
    GROUP BY factor, level_name
    HAVING COUNT(*) >= 30          -- ignore tiny groups, they are just noise
)
SELECT factor,
       COUNT(*)                                      AS levels_compared,
       CAST(MIN(avg_sales_per_book) AS decimal(8,2)) AS lowest_avg_sales_per_book,
       CAST(MAX(avg_sales_per_book) AS decimal(8,2)) AS highest_avg_sales_per_book,
       CAST(MAX(avg_sales_per_book) - MIN(avg_sales_per_book) AS decimal(8,2)) AS spread
FROM per_level
GROUP BY factor;
GO
-- rpt.v_last3_vs_prior_year
/* ---------------- Q1: last 3 months vs same period last year -------- */
CREATE   VIEW rpt.v_last3_vs_prior_year AS
WITH bounds AS (
    SELECT MAX(d.full_date) AS last_date
    FROM dbo.fact_sales f JOIN dbo.dim_date d ON d.date_key = f.order_date_key
),
p AS (
    SELECT DATEADD(MONTH, -2, DATEFROMPARTS(YEAR(last_date), MONTH(last_date), 1)) AS cur_start,
           last_date AS cur_end
    FROM bounds
),
periods AS (
    SELECT 1 AS sort_order, 'Last 3 months' AS period, cur_start AS from_date, cur_end AS to_date FROM p
    UNION ALL
    SELECT 2, 'Same period last year', DATEADD(YEAR, -1, cur_start), DATEADD(YEAR, -1, cur_end) FROM p
)
SELECT pr.sort_order, pr.period, pr.from_date, pr.to_date,
       COUNT(f.sales_key)                 AS units,
       COUNT(DISTINCT f.order_id)         AS orders,
       ISNULL(SUM(f.sales_amount), 0)     AS gross_sales,
       ISNULL(SUM(CASE WHEN f.is_cancelled_or_returned = 0 THEN f.sales_amount END), 0) AS net_sales
FROM periods pr
LEFT JOIN dbo.dim_date d    ON d.full_date BETWEEN pr.from_date AND pr.to_date
LEFT JOIN dbo.fact_sales f  ON f.order_date_key = d.date_key
GROUP BY pr.sort_order, pr.period, pr.from_date, pr.to_date;
GO
-- rpt.v_monthly_sales
/* ---------------- Q1 + Q2: monthly sales with expected range -------- */
CREATE   VIEW rpt.v_monthly_sales AS
WITH bounds AS (
    SELECT MIN(d.full_date) AS first_date, MAX(d.full_date) AS last_date
    FROM dbo.fact_sales f JOIN dbo.dim_date d ON d.date_key = f.order_date_key
),
monthly AS (
    SELECT DATEFROMPARTS(d.year_num, d.month_num, 1) AS month_start,
           d.year_num, d.month_num, d.month_name, d.year_month,
           SUM(f.sales_amount) AS gross_sales,
           SUM(CASE WHEN f.is_cancelled_or_returned = 0 THEN f.sales_amount ELSE 0 END) AS net_sales,
           COUNT(*) AS units,
           COUNT(DISTINCT f.order_id) AS orders
    FROM dbo.fact_sales f JOIN dbo.dim_date d ON d.date_key = f.order_date_key
    GROUP BY d.year_num, d.month_num, d.month_name, d.year_month
),
scaled AS (
    SELECT m.*, b.first_date, b.last_date,
           DATEDIFF(DAY,
               CASE WHEN b.first_date > m.month_start THEN b.first_date ELSE m.month_start END,
               CASE WHEN b.last_date < EOMONTH(m.month_start) THEN b.last_date ELSE EOMONTH(m.month_start) END) + 1
               AS days_with_data,
           DAY(EOMONTH(m.month_start)) AS days_in_month
    FROM monthly m CROSS JOIN bounds b
),
full_month AS (
    SELECT s.*,
           CAST(s.gross_sales * s.days_in_month * 1.0 / s.days_with_data AS decimal(12,2)) AS full_month_sales,
           CASE WHEN s.days_with_data < s.days_in_month THEN 1 ELSE 0 END AS is_partial_month
    FROM scaled s
),
baseline AS (
    SELECT f.*,
           -- partial first month is not a fair baseline, so it is left out
           CASE WHEN f.month_start < f.first_date THEN NULL ELSE f.full_month_sales END AS baseline_sales
    FROM full_month f
),
w AS (
    SELECT b.*,
           LAG(b.full_month_sales, 12) OVER (ORDER BY b.month_start) AS same_month_last_year,
           AVG(b.baseline_sales)   OVER (ORDER BY b.month_start ROWS BETWEEN 12 PRECEDING AND 1 PRECEDING) AS mean_12m,
           STDEV(b.baseline_sales) OVER (ORDER BY b.month_start ROWS BETWEEN 12 PRECEDING AND 1 PRECEDING) AS sd_12m,
           COUNT(b.baseline_sales) OVER (ORDER BY b.month_start ROWS BETWEEN 12 PRECEDING AND 1 PRECEDING) AS months_in_baseline,
           DATEDIFF(MONTH, b.month_start, b.last_date) AS months_ago
    FROM baseline b
)
SELECT month_start, year_num, month_num, month_name, year_month,
       units, orders, gross_sales, net_sales,
       days_with_data, days_in_month, is_partial_month,
       full_month_sales,
       same_month_last_year,
       CAST(100.0 * (full_month_sales - same_month_last_year) / NULLIF(same_month_last_year, 0) AS decimal(6,1)) AS pct_vs_last_year,
       CAST(mean_12m AS decimal(12,2))                   AS expected_sales,
       CAST(mean_12m - 2 * sd_12m AS decimal(12,2))      AS lower_limit,
       CAST(mean_12m + 2 * sd_12m AS decimal(12,2))      AS upper_limit,
       CAST(100.0 * (full_month_sales - mean_12m) / NULLIF(mean_12m, 0) AS decimal(6,1)) AS pct_vs_expected,
       CAST((full_month_sales - mean_12m) / NULLIF(sd_12m, 0) AS decimal(5,2))           AS z_score,
       CASE WHEN months_in_baseline < 12 THEN 'Not enough history'
            WHEN full_month_sales > mean_12m + 2 * sd_12m THEN 'Above range'
            WHEN full_month_sales < mean_12m - 2 * sd_12m THEN 'Below range'
            ELSE 'Within range' END                      AS range_status,
       months_in_baseline,
       months_ago,
       CASE WHEN months_ago < 3  THEN 1 ELSE 0 END       AS is_last_3_months,
       CASE WHEN months_ago < 24 THEN 1 ELSE 0 END       AS is_last_24_months
FROM w;
GO
-- rpt.v_price_pages_correlation
/* ---------------- Q3: correlation of units with price and pages ----- */
CREATE   VIEW rpt.v_price_pages_correlation AS
WITH x AS (
    SELECT CAST(units_sold AS float) AS units,
           CAST(avg_price  AS float) AS price,
           CAST(num_pages  AS float) AS pages
    FROM rpt.v_book_sales
    WHERE units_sold > 0 AND num_pages > 0
)
SELECT COUNT(*) AS books,
       CAST((AVG(units*price) - AVG(units)*AVG(price)) / (STDEVP(units)*STDEVP(price)) AS decimal(5,3)) AS r_units_vs_price,
       CAST((AVG(units*pages) - AVG(units)*AVG(pages)) / (STDEVP(units)*STDEVP(pages)) AS decimal(5,3)) AS r_units_vs_pages,
       CAST((AVG(price*pages) - AVG(price)*AVG(pages)) / (STDEVP(price)*STDEVP(pages)) AS decimal(5,3)) AS r_price_vs_pages
FROM x;
GO
-- rpt.v_sales_by_price_band
/* ---------------- Q3: units sold per price band --------------------- */
CREATE   VIEW rpt.v_sales_by_price_band AS
WITH s AS (
    SELECT f.sales_amount,
           CASE WHEN f.sales_amount <  5 THEN 1 WHEN f.sales_amount < 10 THEN 2
                WHEN f.sales_amount < 15 THEN 3 ELSE 4 END AS band_order
    FROM dbo.fact_sales f
)
SELECT band_order,
       CASE band_order WHEN 1 THEN 'Under 5' WHEN 2 THEN '5 - 9.99'
                       WHEN 3 THEN '10 - 14.99' ELSE '15 and over' END AS price_band,
       COUNT(*)                                AS units_sold,
       SUM(sales_amount)                       AS sales,
       CAST(AVG(sales_amount) AS decimal(6,2)) AS avg_price
FROM s
GROUP BY band_order;
GO
-- dq.usp_run_checks
CREATE   PROCEDURE dq.usp_run_checks
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @run DATETIME2 = SYSDATETIME();

    INSERT INTO dq.check_log (run_time, check_name, dq_dimension, table_name, failed_rows, severity, treatment)
    SELECT @run, check_name, dq_dimension, table_name, failed_rows, severity, treatment
    FROM (
        /* ---------- 1. Integrity ---------- */
        SELECT 'Order line book not in book table' AS check_name, 'Integrity' AS dq_dimension, 'order_line' AS table_name,
               (SELECT COUNT(*) FROM gravity_staging.stg.order_line ol
                 WHERE NOT EXISTS (SELECT 1 FROM gravity_staging.stg.book b WHERE b.book_id = ol.book_id)) AS failed_rows,
               'High' AS severity, 'Map to unknown book (-1)' AS treatment
        UNION ALL
        SELECT 'Order customer not in customer table', 'Integrity', 'cust_order',
               (SELECT COUNT(*) FROM gravity_staging.stg.cust_order o
                 WHERE NOT EXISTS (SELECT 1 FROM gravity_staging.stg.customer c WHERE c.customer_id = o.customer_id)),
               'High', 'Map to unknown customer (-1)'
        UNION ALL
        SELECT 'Order destination not in address table', 'Integrity', 'cust_order',
               (SELECT COUNT(*) FROM gravity_staging.stg.cust_order o
                 WHERE NOT EXISTS (SELECT 1 FROM gravity_staging.stg.address a WHERE a.address_id = o.dest_address_id)),
               'High', 'Map to unknown location (-1)'
        UNION ALL
        SELECT 'Address country missing from region reference', 'Integrity', 'address',
               (SELECT COUNT(*) FROM gravity_staging.stg.address a
                 WHERE NOT EXISTS (SELECT 1 FROM gravity_staging.stg.country_region r WHERE TRY_CAST(r.country_id AS INT) = a.country_id)),
               'High', 'Region = Unknown'
        UNION ALL
        SELECT 'Survey customer ID not a valid customer', 'Integrity', 'survey',
               (SELECT COUNT(*) FROM gravity_staging.stg.survey s
                 WHERE NOT EXISTS (SELECT 1 FROM gravity_staging.stg.customer c WHERE c.customer_id = TRY_CAST(s.customer_id AS INT))),
               'Medium', 'Exclude survey row'

        /* ---------- 2. Completeness ---------- */
        UNION ALL
        SELECT 'Orders with no status history', 'Completeness', 'cust_order',
               (SELECT COUNT(*) FROM gravity_staging.stg.cust_order o
                 WHERE NOT EXISTS (SELECT 1 FROM gravity_staging.stg.order_history h WHERE h.order_id = o.order_id)),
               'Medium', 'latest_order_status = Unknown'
        UNION ALL
        SELECT 'Customers with no survey response', 'Completeness', 'customer',
               (SELECT COUNT(*) FROM gravity_staging.stg.customer c
                 WHERE NOT EXISTS (SELECT 1 FROM gravity_staging.stg.survey s WHERE TRY_CAST(s.customer_id AS INT) = c.customer_id)),
               'Low', 'Survey attributes = No response'
        UNION ALL
        SELECT 'Address missing city or country', 'Completeness', 'address',
               (SELECT COUNT(*) FROM gravity_staging.stg.address WHERE NULLIF(LTRIM(city), '') IS NULL OR country_id IS NULL),
               'High', 'City/country = Unknown'
        UNION ALL
        SELECT 'Order missing order date', 'Completeness', 'cust_order',
               (SELECT COUNT(*) FROM gravity_staging.stg.cust_order WHERE order_date IS NULL),
               'High', 'Date key = -1'

        /* ---------- 3. Validity ---------- */
        UNION ALL
        SELECT 'ISBN13 not 13 characters', 'Validity', 'book',
               (SELECT COUNT(*) FROM gravity_staging.stg.book WHERE isbn13 IS NULL OR LEN(isbn13) <> 13),
               'Low', 'Left-pad with zeros to 13 characters'
        UNION ALL
        SELECT 'Book with 0 pages', 'Validity', 'book',
               (SELECT COUNT(*) FROM gravity_staging.stg.book WHERE num_pages IS NULL OR num_pages <= 0),
               'Low', 'Set num_pages to NULL (unknown)'
        UNION ALL
        SELECT 'Order line price zero, negative or missing', 'Validity', 'order_line',
               (SELECT COUNT(*) FROM gravity_staging.stg.order_line WHERE price IS NULL OR price <= 0),
               'High', 'Reject to dq.fact_rejects'
        UNION ALL
        SELECT 'Order date in the future', 'Validity', 'cust_order',
               (SELECT COUNT(*) FROM gravity_staging.stg.cust_order WHERE order_date > SYSDATETIME()),
               'Medium', 'Investigate'
        UNION ALL
        SELECT 'Status date before order date', 'Validity', 'order_history',
               (SELECT COUNT(*) FROM gravity_staging.stg.order_history h
                  JOIN gravity_staging.stg.cust_order o ON o.order_id = h.order_id
                 WHERE h.status_date < o.order_date),
               'Medium', 'Investigate'
        UNION ALL
        SELECT 'Invalid email format', 'Validity', 'customer',
               (SELECT COUNT(*) FROM gravity_staging.stg.customer WHERE email IS NULL OR email NOT LIKE '%_@_%._%'),
               'Low', 'Email domain = Unknown'
        UNION ALL
        SELECT 'Survey answer not in allowed list', 'Validity', 'survey',
               (SELECT COUNT(*) FROM gravity_staging.stg.survey
                 WHERE LTRIM(RTRIM(heard_about)) NOT IN ('Friend Recommendation','Web Search','Online Advertisement','Physical Store','Other')
                    OR LTRIM(RTRIM(preferred_channel)) NOT IN ('Online','Physical Store','Book Club','Other')),
               'Medium', 'Map to Other'

        /* ---------- 4. Uniqueness ---------- */
        UNION ALL
        SELECT 'Duplicate country names', 'Uniqueness', 'country',
               (SELECT COUNT(*) FROM (SELECT country_name FROM gravity_staging.stg.country
                                      GROUP BY country_name HAVING COUNT(*) > 1) x),
               'Medium', 'Conform to one clean_country_name'
        UNION ALL
        SELECT 'Duplicate customer emails', 'Uniqueness', 'customer',
               (SELECT COUNT(*) FROM (SELECT email FROM gravity_staging.stg.customer
                                      GROUP BY email HAVING COUNT(*) > 1) x),
               'Low', 'Investigate'
        UNION ALL
        SELECT 'Duplicate survey responses per customer', 'Uniqueness', 'survey',
               (SELECT COUNT(*) FROM (SELECT customer_id FROM gravity_staging.stg.survey
                                      GROUP BY customer_id HAVING COUNT(*) > 1) x),
               'Medium', 'Keep first response'
        UNION ALL
        SELECT 'Duplicate book IDs in extract', 'Uniqueness', 'book',
               (SELECT COUNT(*) FROM (SELECT book_id FROM gravity_staging.stg.book
                                      GROUP BY book_id HAVING COUNT(*) > 1) x),
               'High', 'Fail load - extract ran twice?'

        /* ---------- 5. Consistency ---------- */
        UNION ALL
        SELECT 'Order lines shipped to historical/invalid countries', 'Consistency', 'address',
               (SELECT COUNT(*) FROM gravity_staging.stg.order_line ol
                  JOIN gravity_staging.stg.cust_order o ON o.order_id = ol.order_id
                  JOIN gravity_staging.stg.address a ON a.address_id = o.dest_address_id
                  JOIN gravity_staging.stg.country_region r ON TRY_CAST(r.country_id AS INT) = a.country_id
                 WHERE r.country_status <> 'Current'),
               'Medium', 'Map to modern successor where possible, else flag'
        UNION ALL
        SELECT 'Misspelt country names', 'Consistency', 'country',
               (SELECT COUNT(*) FROM gravity_staging.stg.country_region
                 WHERE country_status = 'Current' AND clean_country_name <> country_name),
               'Low', 'Use clean_country_name'
        UNION ALL
        SELECT 'English language code variants', 'Consistency', 'book_language',
               (SELECT COUNT(*) FROM gravity_staging.stg.book_language
                 WHERE language_code IN ('eng','en-US','en-GB','en-CA','enm')),
               'Low', 'Group as language_group = English'
    ) checks;

    -- Return this run's results so they show in SSMS / the SSIS log
    SELECT check_name, dq_dimension, table_name, failed_rows, severity, treatment
    FROM dq.check_log WHERE run_time = @run ORDER BY check_id;
END
GO
-- dq.usp_run_dw_checks
CREATE   PROCEDURE dq.usp_run_dw_checks
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @run DATETIME2 = SYSDATETIME();

    INSERT INTO dq.check_log (run_time, check_name, dq_dimension, table_name, failed_rows, severity, treatment)
    SELECT @run, check_name, dq_dimension, table_name, failed_rows, severity, treatment
    FROM (
        /* ---------- Integrity ---------- */
        SELECT 'Fact rows on an unknown member (-1)' AS check_name, 'Integrity' AS dq_dimension, 'dw.fact_sales' AS table_name,
               (SELECT COUNT(*) FROM dbo.fact_sales
                 WHERE -1 IN (order_date_key, customer_key, book_key, location_key, shipping_key)) AS failed_rows,
               'High' AS severity, 'Investigate source orphans' AS treatment
        UNION ALL
        SELECT 'Order lines lost between staging and warehouse', 'Integrity', 'dw.fact_sales',
               (SELECT COUNT(*) FROM gravity_staging.stg.order_line) - (SELECT COUNT(*) FROM dbo.fact_sales) - (SELECT COUNT(*) FROM dq.fact_rejects),
               'High', 'Reconcile step fails the package'
        UNION ALL
        SELECT 'Fact location differs from order destination', 'Integrity', 'dw.fact_sales',
               (SELECT COUNT(*) FROM dbo.fact_sales f
                  JOIN dbo.dim_location l ON l.location_key = f.location_key
                  JOIN gravity_staging.stg.cust_order o ON o.order_id = f.order_id
                 WHERE o.dest_address_id <> l.address_id),
               'High', 'Check location lookup'

        /* ---------- Completeness ---------- */
        UNION ALL
        SELECT 'Customers with missing survey attributes', 'Completeness', 'dw.dim_customer',
               (SELECT COUNT(*) FROM dbo.dim_customer WHERE customer_key <> -1
                   AND (NULLIF(heard_about, '') IS NULL OR NULLIF(preferred_channel, '') IS NULL)),
               'Low', 'Labelled No response'
        UNION ALL
        SELECT 'Locations with missing country or region', 'Completeness', 'dw.dim_location',
               (SELECT COUNT(*) FROM dbo.dim_location WHERE location_key <> -1
                   AND (country_name IN ('', 'Unknown') OR region IN ('', 'Unknown'))),
               'High', 'Add country to country_region.csv'
        UNION ALL
        SELECT 'Fact lines with unknown order status', 'Completeness', 'dw.fact_sales',
               (SELECT COUNT(*) FROM dbo.fact_sales WHERE latest_order_status = 'Unknown'),
               'Low', 'Expected: orders placed in the last 12 hours have no history yet'

        /* ---------- Validity ---------- */
        UNION ALL
        SELECT 'ISBN13 not 13 characters', 'Validity', 'dw.dim_book',
               (SELECT COUNT(*) FROM dbo.dim_book WHERE book_key <> -1 AND (isbn13 IS NULL OR LEN(isbn13) <> 13)),
               'Low', 'Left-padded in DER Cleanse book'
        UNION ALL
        SELECT 'Book with 0 pages', 'Validity', 'dw.dim_book',
               (SELECT COUNT(*) FROM dbo.dim_book WHERE num_pages <= 0),
               'Low', 'Set to NULL in DER Cleanse book'
        UNION ALL
        SELECT 'Fact line price zero, negative or missing', 'Validity', 'dw.fact_sales',
               (SELECT COUNT(*) FROM dbo.fact_sales WHERE sales_amount IS NULL OR sales_amount <= 0),
               'High', 'Rejected by CSPL Validate price'
        UNION ALL
        SELECT 'Survey answer not in allowed list', 'Validity', 'dw.dim_customer',
               (SELECT COUNT(*) FROM dbo.dim_customer WHERE customer_key <> -1
                   AND (heard_about NOT IN ('Friend Recommendation','Web Search','Online Advertisement','Physical Store','Other','No response')
                     OR preferred_channel NOT IN ('Online','Physical Store','Book Club','Other','No response'))),
               'Medium', 'Map to Other'

        /* ---------- Uniqueness ---------- */
        UNION ALL
        SELECT 'Duplicate business keys in dimensions', 'Uniqueness', 'dw.dim_*',
               (SELECT COUNT(*) FROM (SELECT book_id FROM dbo.dim_book GROUP BY book_id HAVING COUNT(*) > 1) x)
             + (SELECT COUNT(*) FROM (SELECT customer_id FROM dbo.dim_customer GROUP BY customer_id HAVING COUNT(*) > 1) x)
             + (SELECT COUNT(*) FROM (SELECT address_id FROM dbo.dim_location GROUP BY address_id HAVING COUNT(*) > 1) x),
               'High', 'Enforced by unique constraints'
        UNION ALL
        SELECT 'Country name used by more than one source country (not conformed)', 'Uniqueness', 'dw.dim_location',
               (SELECT COUNT(*) FROM (SELECT l.country_name FROM dbo.dim_location l
                                        JOIN gravity_staging.stg.country_region r ON TRY_CAST(r.country_id AS INT) = l.country_id
                                       WHERE l.location_key <> -1 AND l.country_name <> r.clean_country_name
                                       GROUP BY l.country_name) x),
               'Medium', 'Names come from clean_country_name'

        /* ---------- Consistency ---------- */
        UNION ALL
        SELECT 'English language code not grouped as English', 'Consistency', 'dw.dim_book',
               (SELECT COUNT(*) FROM dbo.dim_book
                 WHERE language_code IN ('eng','en-US','en-GB','en-CA','enm') AND language_group <> 'English'),
               'Low', 'language_group in DER Cleanse book'
        UNION ALL
        SELECT 'Misspelt or historical country name in warehouse', 'Consistency', 'dw.dim_location',
               (SELECT COUNT(*) FROM dbo.dim_location l
                  JOIN gravity_staging.stg.country_region r ON TRY_CAST(r.country_id AS INT) = l.country_id
                 WHERE l.country_name <> r.clean_country_name),
               'Low', 'Use clean_country_name'
        UNION ALL
        SELECT 'Sales total differs from source (valid lines)', 'Consistency', 'dw.fact_sales',
               CASE WHEN (SELECT SUM(sales_amount) FROM dbo.fact_sales)
                       = (SELECT SUM(price) FROM gravity_staging.stg.order_line WHERE price > 0) THEN 0 ELSE 1 END,
               'High', 'Investigate'
    ) checks;

    SELECT check_name, dq_dimension, table_name, failed_rows, severity, treatment
    FROM dq.check_log WHERE run_time = @run ORDER BY check_id;
END
GO
-- etl.usp_load_dim_date
CREATE   PROCEDURE etl.usp_load_dim_date
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @start    DATE = (SELECT CAST(config_value AS DATE) FROM etl.config WHERE config_key = 'dim_date_start');
    DECLARE @end      DATE = (SELECT CAST(config_value AS DATE) FROM etl.config WHERE config_key = 'dim_date_end');
    DECLARE @campaign DATE = (SELECT CAST(config_value AS DATE) FROM etl.config WHERE config_key = 'campaign_start_date');

    DELETE FROM dbo.dim_date WHERE date_key <> -1;

    WITH n AS (
        SELECT TOP (DATEDIFF(DAY, @start, @end) + 1)
               ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1 AS i
        FROM sys.all_objects a CROSS JOIN sys.all_objects b
    ), d AS (
        SELECT DATEADD(DAY, i, @start) AS dt FROM n
    )
    INSERT INTO dbo.dim_date (date_key, full_date, day_of_month, day_name, month_num, month_name,
                              quarter_num, quarter_label, year_num, year_month, year_quarter, campaign_period)
    SELECT CONVERT(INT, FORMAT(dt, 'yyyyMMdd')),
           dt,
           DAY(dt),
           DATENAME(WEEKDAY, dt),
           MONTH(dt),
           DATENAME(MONTH, dt),
           DATEPART(QUARTER, dt),
           'Q' + CAST(DATEPART(QUARTER, dt) AS CHAR(1)),
           YEAR(dt),
           FORMAT(dt, 'yyyy-MM'),
           CAST(YEAR(dt) AS CHAR(4)) + '-Q' + CAST(DATEPART(QUARTER, dt) AS CHAR(1)),
           CASE WHEN dt < @campaign THEN 'Pre-campaign' ELSE 'Post-campaign' END
    FROM d;
END
GO
-- etl.usp_prepare_full_load
CREATE   PROCEDURE etl.usp_prepare_full_load
AS
BEGIN
    SET NOCOUNT ON;
    -- Fact first (it references every dimension)
    TRUNCATE TABLE dbo.fact_sales;
    TRUNCATE TABLE dq.fact_rejects;

    DELETE FROM dbo.dim_customer        WHERE customer_key <> -1;
    DELETE FROM dbo.dim_book            WHERE book_key     <> -1;
    DELETE FROM dbo.dim_location        WHERE location_key <> -1;
    DELETE FROM dbo.dim_shipping_method WHERE shipping_key <> -1;
    DELETE FROM dbo.dim_date            WHERE date_key     <> -1;

    -- Restart surrogate keys at 1 so every reload gives the same keys.
    -- RESEED behaves differently on a table whose identity has never been used
    -- (the next key is the reseed value itself, not reseed + 1), so reseed to 1 in
    -- that case and to 0 otherwise. Without this, the first load numbered keys from 0.
    DECLARE @t SYSNAME, @seed INT;
    DECLARE c CURSOR LOCAL FAST_FORWARD FOR
        SELECT 'dbo.' + name FROM (VALUES ('dim_customer'), ('dim_book'), ('dim_location'), ('dim_shipping_method')) v(name);
    OPEN c;
    FETCH NEXT FROM c INTO @t;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @seed = CASE WHEN (SELECT last_value FROM sys.identity_columns WHERE object_id = OBJECT_ID(@t)) IS NULL THEN 1 ELSE 0 END;
        DBCC CHECKIDENT (@t, RESEED, @seed) WITH NO_INFOMSGS;
        FETCH NEXT FROM c INTO @t;
    END
    CLOSE c; DEALLOCATE c;
END
GO
-- rpt.v_country_quarterly
/* ---------------- Q5: sales per country per quarter ----------------- */
CREATE   VIEW rpt.v_country_quarterly AS
WITH bounds AS (
    SELECT MIN(d.full_date) AS first_date, MAX(d.full_date) AS last_date
    FROM dbo.fact_sales f JOIN dbo.dim_date d ON d.date_key = f.order_date_key
),
q AS (
    SELECT l.country_name, l.region, d.year_num, d.quarter_num, d.year_quarter,
           DATEFROMPARTS(d.year_num, (d.quarter_num - 1) * 3 + 1, 1) AS quarter_start,
           SUM(f.sales_amount) AS sales,
           COUNT(*)            AS units
    FROM dbo.fact_sales f
    JOIN dbo.dim_date d     ON d.date_key = f.order_date_key
    JOIN dbo.dim_location l ON l.location_key = f.location_key
    GROUP BY l.country_name, l.region, d.year_num, d.quarter_num, d.year_quarter
)
SELECT q.*,
       r.sales_rank,
       CASE WHEN r.sales_rank <= 10 THEN 1 ELSE 0 END AS is_top_10_country,
       -- first and last quarters only have part of their data
       CASE WHEN q.quarter_start < b.first_date
              OR EOMONTH(DATEADD(MONTH, 2, q.quarter_start)) > b.last_date THEN 1 ELSE 0 END AS is_partial_quarter
FROM q
JOIN rpt.v_country_sales r ON r.country_name = q.country_name
CROSS JOIN bounds b;
GO
PRINT 'gravity_dw snapshot load complete.';
GO
